-- S8 前置：媒体 GUID 修正（路径派生，GetNewItemId 公式对齐）
-- 生成器：tests/perf/gen-media-guid-fix.ps1；执行顺序：path 修正之后
CREATE TEMP TABLE guid_fix (id bigint PRIMARY KEY, new_guid uuid);
UPDATE media_items m SET guid = g.new_guid FROM guid_fix g WHERE m.id = g.id;
SELECT 'guids fixed' AS c, count(*) FROM media_items m JOIN guid_fix g ON m.id = g.id;
